class Solution {
public:
    int findSmallestInteger(vector<int>& nums, int value) {
        unordered_map<int,int> cnt;
        for (int x : nums) {
            int r = ((x % value) + value) % value;
            cnt[r]++;
        }
        unordered_map<int,int> used;
        int mex = 0;
        while (true) {
            int r = mex % value;
            if (cnt[r] > used[r]) {
                used[r]++;
                mex++;
            } else {
                break;
            }
        }
        return mex;
    }
};
